package org.apache.commons.lang3.text.translate;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class NumericEntityUnescaper_ESTest_test8 extends NumericEntityUnescaper_ESTest_scaffolding {

    /**
     * An incomplete numeric entity at the end of the input is left untouched.
     *
     * The input ends with "&#X", which begins a hexadecimal entity but has no
     * digits and no terminating semicolon. With the default options the
     * unescaper cannot interpret it, so the entire input is copied verbatim.
     */
    @Test(timeout = 4000)
    public void test8() throws Throwable {
        // Default options (no OPTION values supplied).
        NumericEntityUnescaper unescaper = new NumericEntityUnescaper(new NumericEntityUnescaper.OPTION[0]);

        // Three NUL characters (the default char value) followed by an
        // incomplete entity "&#X".
        char[] chars = new char[6];
        chars[3] = '&';
        chars[4] = '#';
        chars[5] = 'X';
        CharBuffer input = CharBuffer.wrap(chars);

        String result = unescaper.translate((CharSequence) input);

        // Nothing is unescaped: the input is returned unchanged, so the result
        // equals the original characters (three NULs followed by "&#X").
        String expectedUnchangedInput = new String(chars);
        assertEquals("���&#X", result);
    }
}
